// streamsItem seeds an item shaped for the streams lane: a settled `ready`
// metadata record (sources + _stages populated) whose parsed carries the
// absolute_path stamp the pack seam consumes. Returned with its row.
func streamsItem(t *testing.T, s *store.Store, libID int64, id string) store.Item {
	t.Helper()
	doc := baseDoc("Movies/Hostile Container.mkv")
	doc["parsed"].(map[string]any)["absolute_path"] = "/library/Movies/Hostile Container.mkv"
	doc["ffprobe"] = map[string]any{"format": map[string]any{"duration": "12.0"}}
	doc["sources"] = map[string]any{"tv-parser": map[string]any{"title": "done"}}
	doc["_stages"] = []map[string]any{{"stage": "metadata_source", "plugin_id": "tv-parser", "status": "ok"}}
	putItem(t, s, id, libID, statusReady, doc)
	it, err := s.GetItem(context.Background(), id)
	if err != nil {
		t.Fatalf("GetItem %s: %v", id, err)
	}
	return it
}

// streamsState polls the item until doc["streams"].state is want (or fails).
func streamsState(t *testing.T, s *store.Store, id, want string, timeout time.Duration) map[string]any {
	t.Helper()
	deadline := time.Now().Add(timeout)
	for time.Now().Before(deadline) {
		it, err := s.GetItem(context.Background(), id)
		if err == nil {
			var doc map[string]any
			_ = json.Unmarshal(it.Document, &doc)
			if st, ok := doc["streams"].(map[string]any); ok && st["state"] == want {
				return st
			}
		}
		time.Sleep(time.Millisecond)
	}
	t.Fatalf("item %s streams state never reached %q (timeout %v)", id, want, timeout)
	return nil
}

// packRecord collects what a fake PackItem seam received.
type packRecord struct {
	itemID, absPath string
	ffprobe         map[string]any
	voiceovers      []string
	calls           int32
}

// packSeam returns a Deps.PackItem func-field over the record: it counts calls,
// captures its inputs, sleeps delay, and returns outcome/err.
func packSeam(rec *packRecord, delay time.Duration, outcome PackOutcome, err error) func(context.Context, string, string, map[string]any, []string) (PackOutcome, error) {
	return func(_ context.Context, itemID, absPath string, ffprobe map[string]any, voiceovers []string) (PackOutcome, error) {
		atomic.AddInt32(&rec.calls, 1)
		rec.itemID, rec.absPath, rec.ffprobe, rec.voiceovers = itemID, absPath, ffprobe, voiceovers
		if delay > 0 {
			time.Sleep(delay)
		}
		return outcome, err
	}
}

// TestStreamsLane is the spec floor for "Packaging work rides the enrichment
// queue" (both scenarios) and "Failed pack cools down flat": the lane drains
// under lease semantics, records pack_failed ledger rows under __streams__
// with a flat 30-day cooldown, and never moves metadata-completion state.
func TestStreamsLane(t *testing.T) {
	ctx := context.Background()

	t.Run("success_persists_streams_and_keeps_metadata", func(t *testing.T) {
		s, reg := queueTestStore(t)
		libID, _ := s.CreateLibrary(ctx, "tv", filepath.Join(t.TempDir(), "lib"), "TV")
		before := streamsItem(t, s, libID, "i_pack_ok")

		rec := &packRecord{}
		q := NewQueue(Deps{Store: s, Modules: reg, PackItem: packSeam(rec, 0, PackOutcome{Playlist: "/media/i_pack_ok/ab12cd34/index.m3u8", Nonce: "ab12cd34"}, nil)}, QueueConfig{})
		q.workStreams(ctx, "i_pack_ok")

		st := streamsState(t, s, "i_pack_ok", "complete", time.Second)
		if st["playlist"] != "/media/i_pack_ok/ab12cd34/index.m3u8" || st["nonce"] != "ab12cd34" {
			t.Fatalf("persisted streams = %v, want the PackOutcome pointer", st)
		}
		// A codec-less outcome (playback-capability-gate D2) persists as an
		// absent key — never an empty array.
		if _, ok := st["codecs"]; ok {
			t.Fatalf("persisted streams carries codecs %v, want an absent key on a codec-less outcome", st["codecs"])
		}
		// The seam received the item id, the stamped absolute path, and the
		// stored ffprobe facts (Interface 2 wiring). The fixture carries no
		// audio sidecars, so the voiceover facts are empty.
		if rec.itemID != "i_pack_ok" || rec.absPath != "/library/Movies/Hostile Container.mkv" || rec.ffprobe == nil || rec.voiceovers != nil {
			t.Fatalf("PackItem inputs = %+v, want id + absolute_path + ffprobe + no voiceovers", rec)
		}
		// Metadata completion is unaffected: status ready, namespaces as before.
		it := mustGetItem(t, s, "i_pack_ok")
		if it.Status != statusReady {
			t.Fatalf("status = %q, want untouched %q", it.Status, statusReady)
		}
		assertMetadataUntouched(t, before.Document, it.Document)
		// Success clears (never writes) the pack ledger row.
		rows, _ := s.ListFailures(ctx)
		for _, r := range rows {
			if r.ItemID == "i_pack_ok" && r.PluginID == streamsLaneID {
				t.Fatalf("pack ledger row written on success: %+v", r)
			}
		}
	})

	// The recorded codec record rides the completion write (playback-capability-
	// gate D2): doc["streams"].codecs, in the PackOutcome's rendition order.
	t.Run("success_persists_recorded_codecs", func(t *testing.T) {
		s, reg := queueTestStore(t)
		libID, _ := s.CreateLibrary(ctx, "tv", filepath.Join(t.TempDir(), "lib"), "TV")
		streamsItem(t, s, libID, "i_pack_cdc")

		rec := &packRecord{}
		q := NewQueue(Deps{Store: s, Modules: reg, PackItem: packSeam(rec, 0, PackOutcome{
			Playlist: "/media/i_pack_cdc/ab12cd34/index.m3u8",
			Nonce:    "ab12cd34",
			Codecs:   []string{"avc1.640029", "mp4a.40.2"},
		}, nil)}, QueueConfig{})
		q.workStreams(ctx, "i_pack_cdc")

		st := streamsState(t, s, "i_pack_cdc", "complete", time.Second)
		got, ok := st["codecs"].([]any)
		if !ok || len(got) != 2 || got[0] != "avc1.640029" || got[1] != "mp4a.40.2" {
			t.Fatalf("persisted codecs = %v, want the PackOutcome record in rendition order", st["codecs"])
		}
	})

	t.Run("pack_seam_carries_document_order_audio_sidecars", func(t *testing.T) {
		s, reg := queueTestStore(t)
		libID, _ := s.CreateLibrary(ctx, "tv", filepath.Join(t.TempDir(), "lib"), "TV")
		doc := baseDoc("Movies/Hostile Container.mkv")
		doc["parsed"].(map[string]any)["absolute_path"] = "/library/Movies/Hostile Container.mkv"
		doc["parsed"].(map[string]any)["sidecars"] = []any{
			map[string]any{"relative_path": "Rus subs/ep01.srt", "kind": "subtitle", "language": "rus"},
			map[string]any{"relative_path": "Rus sound/ep01.mka", "kind": "audio", "language": "rus"},
			map[string]any{"relative_path": "Rus sound/ep01.2.mka", "kind": "audio"},
		}
		doc["parsed"].(map[string]any)["series_sidecars"] = []any{
			map[string]any{"relative_path": "OST/theme.flac", "kind": "audio"},
		}
		b, _ := json.Marshal(doc)
		if err := s.PutItem(ctx, store.Item{
			ID: "i_pack_vo", ModuleID: "tv", LibraryID: libID, FileID: "i_pack_vo",
			RelativePath: "Movies/Hostile Container.mkv", MediaType: "tv",
			Document: b, Status: statusReady,
		}); err != nil {
			t.Fatalf("PutItem: %v", err)
		}

		rec := &packRecord{}
		q := NewQueue(Deps{Store: s, Modules: reg, PackItem: packSeam(rec, 0, PackOutcome{Playlist: "/p", Nonce: "n"}, nil)}, QueueConfig{})
		q.workStreams(ctx, "i_pack_vo")

		// Only the episode-linked AUDIO sidecars pass, in document order, as
		// absolute paths derived from the episode's stored facts — the
		// subtitle and the serial-level OST never ride the seam.
		want := []string{
			"/library/Rus sound/ep01.mka",
			"/library/Rus sound/ep01.2.mka",
		}
		if len(rec.voiceovers) != len(want) {
			t.Fatalf("voiceovers = %v, want %v", rec.voiceovers, want)
		}
		for i := range want {
			if rec.voiceovers[i] != want[i] {
				t.Fatalf("voiceovers = %v, want %v", rec.voiceovers, want)
			}
		}
	})

	t.Run("terminal_failure_records_flat_pack_failed", func(t *testing.T) {
		withFixedClock(t, time.Date(2026, 8, 3, 12, 0, 0, 0, time.UTC))
		s, reg := queueTestStore(t)
		libID, _ := s.CreateLibrary(ctx, "tv", filepath.Join(t.TempDir(), "lib"), "TV")
		before := streamsItem(t, s, libID, "i_pack_fail")

		rec := &packRecord{}
		q := NewQueue(Deps{Store: s, Modules: reg, PackItem: packSeam(rec, 0, PackOutcome{}, errors.New("ffmpeg exploded"))}, QueueConfig{Backoff: time.Millisecond})
		q.workStreams(ctx, "i_pack_fail")

		st := streamsState(t, s, "i_pack_fail", "failed", time.Second)
		if st["failed_at"] == "" {
			t.Fatalf("failed streams doc missing failed_at: %v", st)
		}
		row := packLedgerRow(t, s, "i_pack_fail")
		if row.Status != ledgerPackFailed {
			t.Fatalf("ledger status = %q, want %q", row.Status, ledgerPackFailed)
		}
		want := now().Add(defaultNoDataCool)
		if row.NextEligibleAt.Before(now().Add(defaultNoDataCool-time.Second)) || row.NextEligibleAt.After(now().Add(defaultNoDataCool+time.Second)) {
			t.Fatalf("NextEligibleAt = %v, want ~now+30d flat (%v)", row.NextEligibleAt, want)
		}
		// A repeated failure shortly after must NOT double the cooldown (the
		// play-time retry re-enqueues; doubling would punish explicit retries).
		q.workStreams(ctx, "i_pack_fail")
		row2 := packLedgerRow(t, s, "i_pack_fail")
		if !row2.NextEligibleAt.Equal(row.NextEligibleAt) {
			t.Fatalf("second failure NextEligibleAt = %v, first = %v (cooldown must stay flat)", row2.NextEligibleAt, row.NextEligibleAt)
		}
		if row2.Attempts != row.Attempts+1 {
			t.Fatalf("attempts = %d, want %d (rounds distinguishable)", row2.Attempts, row.Attempts+1)
		}
		// Metadata completion is unaffected on the failure path too.
		it := mustGetItem(t, s, "i_pack_fail")
		if it.Status != statusReady {
			t.Fatalf("status = %q, want untouched %q", it.Status, statusReady)
		}
		assertMetadataUntouched(t, before.Document, it.Document)
	})

	t.Run("lease_held_for_the_duration_of_the_run", func(t *testing.T) {
		s, reg := queueTestStore(t)
		libID, _ := s.CreateLibrary(ctx, "tv", filepath.Join(t.TempDir(), "lib"), "TV")
		streamsItem(t, s, libID, "i_pack_lease")

		rec := &packRecord{}
		q := NewQueue(Deps{Store: s, Modules: reg, PackItem: packSeam(rec, 40*time.Millisecond, PackOutcome{Playlist: "/p", Nonce: "n"}, nil)}, QueueConfig{LeaseTTL: time.Minute})
		var wg sync.WaitGroup
		start := make(chan struct{})
		for i := 0; i < 2; i++ {
			wg.Add(1)
			go func() {
				defer wg.Done()
				<-start
				q.workStreams(ctx, "i_pack_lease")
			}()
		}
		close(start)
		wg.Wait()
		if calls := atomic.LoadInt32(&rec.calls); calls != 1 {
			t.Fatalf("PackItem calls = %d, want 1 (the lease serializes the lane within-item)", calls)
		}
	})

	t.Run("long_run_renews_its_lease", func(t *testing.T) {
		s, reg := queueTestStore(t)
		libID, _ := s.CreateLibrary(ctx, "tv", filepath.Join(t.TempDir(), "lib"), "TV")
		streamsItem(t, s, libID, "i_pack_renew")

		rec := &packRecord{}
		q := NewQueue(Deps{Store: s, Modules: reg, PackItem: packSeam(rec, 120*time.Millisecond, PackOutcome{Playlist: "/p", Nonce: "n"}, nil)}, QueueConfig{LeaseTTL: 40 * time.Millisecond})

		done := make(chan struct{})
		go func() { defer close(done); q.workStreams(ctx, "i_pack_renew") }()
		time.Sleep(70 * time.Millisecond) // the run has outlived one TTL; renewal must have kept it alive
		if q.leases.acquire("i_pack_renew", "other", time.Minute) {
			t.Fatal("acquire succeeded mid-run — a live long run was treated as dead (renewal broken)")
		}
		<-done
		if !q.leases.acquire("i_pack_renew", "other", time.Minute) {
			t.Fatal("acquire failed after the run ended — the lease was not released")
		}
	})

	t.Run("lane_disabled_is_a_noop", func(t *testing.T) {
		s, reg := queueTestStore(t)
		libID, _ := s.CreateLibrary(ctx, "tv", filepath.Join(t.TempDir(), "lib"), "TV")
		before := streamsItem(t, s, libID, "i_pack_off")
		q := NewQueue(Deps{Store: s, Modules: reg}, QueueConfig{})
		q.workStreams(ctx, "i_pack_off") // nil PackItem: no panic, no write
		it := mustGetItem(t, s, "i_pack_off")
		var doc map[string]any
		_ = json.Unmarshal(it.Document, &doc)
		if _, ok := doc["streams"]; ok {
			t.Fatalf("disabled lane wrote doc[streams]: %v", doc["streams"])
		}
		_ = before
	})

	t.Run("enqueue_pack_drains_through_the_worker", func(t *testing.T) {
		s, reg := queueTestStore(t)
		libID, _ := s.CreateLibrary(ctx, "tv", filepath.Join(t.TempDir(), "lib"), "TV")
		streamsItem(t, s, libID, "i_pack_q")

		rec := &packRecord{}
		q := NewQueue(Deps{Store: s, Modules: reg, PackItem: packSeam(rec, 0, PackOutcome{Playlist: "/media/i_pack_q/n0/index.m3u8", Nonce: "n0"}, nil)}, QueueConfig{})
		// The fixture item still owes tmdb/frame-grabber metadata work, and the
		// Start sweep derives it; without a resolver the metadata drain would
		// nil-deref at chain.go:61 (races the lane drain, flaking the package).
		// An empty mapResolver marks every metadata source unavailable — the
		// soft, settle-terminal outcome (settle_gate_parity) — leaving the lane
		// drain this subtest exists for.
		q.resolve = mapResolver{}.resolver()
		if err := q.Start(ctx); err != nil {
			t.Fatalf("Start: %v", err)
		}
		defer q.Stop()
		if err := q.EnqueuePack("i_pack_q"); err != nil {
			t.Fatalf("EnqueuePack: %v", err)
		}
		streamsState(t, s, "i_pack_q", "complete", 2*time.Second)
	})
}

// TestPackPolicyRefusal is the acceptance test for the build-time gate
// (playback-capability-gate 1.3, D4): a PackItem seam returning PolicyRefusal
// — the gate closed between enqueue and build — persists state failed with
// the gate's state_reason token and writes NO pack_failed ledger row, so the
// item never enters a cooldown; with the knob on again the frontier's
// eligibility (no CoolUntil — no row exists to read) re-enqueues it and the
// heal run completes, the ledger still empty.
func TestPackPolicyRefusal(t *testing.T) {
	ctx := context.Background()

	t.Run("refusal_persists_failed_without_a_ledger_row", func(t *testing.T) {
		withFixedClock(t, time.Date(2026, 10, 31, 12, 0, 0, 0, time.UTC))
		s, reg := queueTestStore(t)
		libID, _ := s.CreateLibrary(ctx, "tv", filepath.Join(t.TempDir(), "lib"), "TV")
		streamsItem(t, s, libID, "i_pack_policy")

		rec := &packRecord{}
		q := NewQueue(Deps{Store: s, Modules: reg, PackItem: packSeam(rec, 0, PackOutcome{}, PolicyRefusal{Reason: "codec_not_opted_in"})}, QueueConfig{})
		q.workStreams(ctx, "i_pack_policy")

		st := streamsState(t, s, "i_pack_policy", "failed", time.Second)
		// The reason is the BARE gate token — the descriptor's own
		// state_reason spelling (D1), never a wrapped error message.
		if st["reason"] != "codec_not_opted_in" {
			t.Fatalf("reason = %v, want the bare codec_not_opted_in token", st["reason"])
		}
		if st["failed_at"] == "" {
			t.Fatalf("failed streams doc missing failed_at: %v", st)
		}
		rows, err := s.ListFailures(ctx)
		if err != nil {
			t.Fatalf("ListFailures: %v", err)
		}
		if len(rows) != 0 {
			t.Fatalf("ledger rows = %d, want 0 — a policy refusal never charges the cooldown", len(rows))
		}
	})

	t.Run("real_pack_failure_still_records_the_row", func(t *testing.T) {
		s, reg := queueTestStore(t)
		libID, _ := s.CreateLibrary(ctx, "tv", filepath.Join(t.TempDir(), "lib"), "TV")
		streamsItem(t, s, libID, "i_pack_realfail")

		rec := &packRecord{}
		q := NewQueue(Deps{Store: s, Modules: reg, PackItem: packSeam(rec, 0, PackOutcome{}, errors.New("ffmpeg exploded"))}, QueueConfig{})
		q.workStreams(ctx, "i_pack_realfail")

		streamsState(t, s, "i_pack_realfail", "failed", time.Second)
		packLedgerRow(t, s, "i_pack_realfail") // fails the test when absent
	})

	t.Run("knob_on_heals_through_frontier_eligibility", func(t *testing.T) {
		s, reg := queueTestStore(t)
		libID, _ := s.CreateLibrary(ctx, "tv", filepath.Join(t.TempDir(), "lib"), "TV")
		streamsItem(t, s, libID, "i_pack_heal")

		refused := true
		pack := func(context.Context, string, string, map[string]any, []string) (PackOutcome, error) {
			if refused {
				return PackOutcome{}, PolicyRefusal{Reason: "codec_not_opted_in"}
			}
			return PackOutcome{Playlist: "/media/i_pack_heal/n1/index.m3u8", Nonce: "n1"}, nil
		}
		q := NewQueue(Deps{Store: s, Modules: reg, PackItem: pack}, QueueConfig{})
		q.workStreams(ctx, "i_pack_heal")
		streamsState(t, s, "i_pack_heal", "failed", time.Second)

		// Knob on: no ledger row exists, so the frontier's CoolUntil is zero
		// and the re-enqueue reaches the lane; the healed run completes.
		refused = false
		q.resolve = mapResolver{}.resolver()
		if err := q.Start(ctx); err != nil {
			t.Fatalf("Start: %v", err)
		}
		defer q.Stop()
		if err := q.EnqueuePack("i_pack_heal"); err != nil {
			t.Fatalf("EnqueuePack: %v", err)
		}
		st := streamsState(t, s, "i_pack_heal", "complete", 2*time.Second)
		if st["nonce"] != "n1" {
			t.Fatalf("nonce = %v, want the healed build n1", st["nonce"])
		}
		rows, err := s.ListFailures(ctx)
		if err != nil {
			t.Fatalf("ListFailures: %v", err)
		}
		if len(rows) != 0 {
			t.Fatalf("ledger rows = %d, want 0 — the heal needs no ledger to clear", len(rows))
		}
	})
}

// packLedgerRow fetches the item's __streams__ ledger row (fails when absent).
func packLedgerRow(t *testing.T, s *store.Store, itemID string) store.FailureRow {
	t.Helper()
	rows, err := s.ListFailures(context.Background())
	if err != nil {
		t.Fatalf("ListFailures: %v", err)
	}
	for _, r := range rows {
		if r.ItemID == itemID && r.PluginID == streamsLaneID {
			return r
		}
	}
	t.Fatalf("no __streams__ ledger row for %s; rows=%v", itemID, rows)
	return store.FailureRow{}
}

// mustGetItem loads an item or fails the test.
func mustGetItem(t *testing.T, s *store.Store, id string) store.Item {
	t.Helper()
	it, err := s.GetItem(context.Background(), id)
	if err != nil {
		t.Fatalf("GetItem %s: %v", id, err)
	}
	return it
}

// assertMetadataUntouched asserts the document's metadata-completion namespaces
// (sources, _provenance, _view, _stages) are byte-identical after a lane run —
// the lane's only sanctioned write is the `streams` namespace.
func assertMetadataUntouched(t *testing.T, beforeRaw, afterRaw json.RawMessage) {
	t.Helper()
	var before, after map[string]json.RawMessage
	if err := json.Unmarshal(beforeRaw, &before); err != nil {
		t.Fatalf("unmarshal before: %v", err)
	}
	if err := json.Unmarshal(afterRaw, &after); err != nil {
		t.Fatalf("unmarshal after: %v", err)
	}
	for _, ns := range []string{"sources", "_provenance", "_view", "_stages"} {
		if string(before[ns]) != string(after[ns]) {
			t.Fatalf("metadata namespace %s changed by the streams lane:\nbefore %s\nafter  %s", ns, before[ns], after[ns])
		}
	}
}

// TestStreamsLaneAfterPackPersist is the acceptance test for the eviction seam
// (playback-capability-gate D5): a non-nil Deps.AfterPackPersist runs exactly
// once with the persisted build's item id and nonce, only AFTER the success
// persistStreams — the document already names the new build when the seam
// fires — and never on the failure path (pack error or policy refusal). nil
// stays a no-op.
func TestStreamsLaneAfterPackPersist(t *testing.T) {
	ctx := context.Background()

	t.Run("success_calls_seam_after_persist", func(t *testing.T) {
		s, reg := queueTestStore(t)
		libID, _ := s.CreateLibrary(ctx, "tv", filepath.Join(t.TempDir(), "lib"), "TV")
		streamsItem(t, s, libID, "i_evict_ok")

		type call struct {
			itemID, keepNonce string
			persistedState    string // doc["streams"].state as observed INSIDE the seam
			persistedNonce    string
		}
		var calls []call
		q := NewQueue(Deps{
			Store:    s,
			Modules:  reg,
			PackItem: packSeam(&packRecord{}, 0, PackOutcome{Playlist: "/media/i_evict_ok/ab12cd34/index.m3u8", Nonce: "ab12cd34"}, nil),
			AfterPackPersist: func(itemID, keepNonce string) {
				doc := decodeDoc(mustGetItem(t, s, itemID).Document)
				st, _ := doc["streams"].(map[string]any)
				state, _ := st["state"].(string)
				nonce, _ := st["nonce"].(string)
				calls = append(calls, call{itemID, keepNonce, state, nonce})
			},
		}, QueueConfig{})
		q.workStreams(ctx, "i_evict_ok")

		if len(calls) != 1 {
			t.Fatalf("AfterPackPersist calls = %d, want exactly 1", len(calls))
		}
		got := calls[0]
		if got.itemID != "i_evict_ok" || got.keepNonce != "ab12cd34" {
			t.Fatalf("AfterPackPersist args = (%q, %q), want (i_evict_ok, ab12cd34)", got.itemID, got.keepNonce)
		}
		// The ordering is load-bearing (D5): when the seam fires, the document
		// already names the new build — the eviction can never delete the
		// descriptor's current build.
		if got.persistedState != "complete" || got.persistedNonce != "ab12cd34" {
			t.Fatalf("seam ran before the success persist: observed streams state=%q nonce=%q, want complete/ab12cd34", got.persistedState, got.persistedNonce)
		}
	})

	t.Run("failure_path_never_calls_seam", func(t *testing.T) {
		s, reg := queueTestStore(t)
		libID, _ := s.CreateLibrary(ctx, "tv", filepath.Join(t.TempDir(), "lib"), "TV")
		streamsItem(t, s, libID, "i_evict_fail")

		calls := 0
		q := NewQueue(Deps{
			Store:            s,
			Modules:          reg,
			PackItem:         packSeam(&packRecord{}, 0, PackOutcome{}, errors.New("ffmpeg exploded")),
			AfterPackPersist: func(itemID, keepNonce string) { calls++ },
		}, QueueConfig{Backoff: time.Millisecond})
		q.workStreams(ctx, "i_evict_fail")
		if calls != 0 {
			t.Fatalf("AfterPackPersist called %d times on the pack-failure path, want 0", calls)
		}

		// The policy-refusal branch (playback-capability-gate D4) is also a
		// failure path: a knob setting never evicts either.
		streamsItem(t, s, libID, "i_evict_refuse")
		q2 := NewQueue(Deps{
			Store:   s,
			Modules: reg,
			PackItem: func(context.Context, string, string, map[string]any, []string) (PackOutcome, error) {
				return PackOutcome{}, PolicyRefusal{Reason: "codec_not_opted_in"}
			},
			AfterPackPersist: func(itemID, keepNonce string) { calls++ },
		}, QueueConfig{})
		q2.workStreams(ctx, "i_evict_refuse")
		if calls != 0 {
			t.Fatalf("AfterPackPersist called %d times on the policy-refusal path, want 0", calls)
		}
	})
}
